
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_hcth_407p_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_hcth_407p", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.523238898263379e+00, -4.431919142656285e+00, -4.304059723418551e+00, -4.127170916231628e+00, -3.886662113776043e+00, -3.567801705119832e+00, -3.160421732850939e+00, -2.668076588775396e+00, -2.123646027529732e+00, -1.604035674718806e+00, -1.136943769151668e+00, -7.725700770953510e-01, -6.678318448796715e-01, -5.409084451366738e-01, -3.956965435768039e-01, -2.548913252656141e-01, -1.387987136647846e-01, -6.930720247203954e-02, -1.953962455704200e-02, -2.533549524929982e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


